def render(sections):
    out = [f'<p>{sections[0][1]}</p>', '<h2>Resposta rápida</h2><p>Comece por um tema específico, compartilhe apenas o necessário e respeite os limites de todos. O Disque Amizade funciona em modelo freemium: recursos básicos podem estar disponíveis sem custo e há opções premium opcionais.</p>']
    out += [f'<h2>{h}</h2><p>{p}</p>' for h, p in sections[1:]]
    out.append('<h2>Como transformar uma conversa em hábito</h2><p>Reserve alguns minutos, escolha um assunto que realmente desperte sua curiosidade e observe a qualidade das respostas. Uma boa interação não precisa durar horas nem produzir uma amizade imediata. Faça uma pergunta, conte uma experiência relacionada e deixe a outra pessoa escolher quanto deseja compartilhar. Se houver afinidade, volte outro dia; se não houver, agradeça e procure um ambiente diferente. Evite copiar mensagens em massa, pressionar por contato externo ou medir o valor da conversa pela quantidade de notificações. O objetivo de um bate-papo online é criar presença e troca, não acumular contatos. Com o tempo, você aprende quais temas aproximam, quais limites precisa comunicar e quais salas combinam com seu ritmo. Essa prática também torna mais fácil reconhecer conversas respeitosas e sair rapidamente das que não fazem bem.</p>')
    out += ['<h2>Erros comuns</h2><ul><li>Esperar intimidade instantânea.</li><li>Compartilhar dados pessoais para provar confiança.</li><li>Insistir depois de um limite claro.</li><li>Ignorar sinais de golpe ou desrespeito.</li></ul>', '<h2>Conclusão</h2><p>Conversas boas começam devagar, com curiosidade, autonomia e limites claros.</p><p><strong>Experimente o Disque Amizade</strong> e encontre uma nova conversa hoje.</p>', '<h2>FAQ</h2><h3>O Disque Amizade é totalmente gratuito?</h3><p>Não. É freemium: há recursos básicos que podem estar disponíveis sem custo e funcionalidades premium opcionais.</p><h3>Preciso revelar meu nome real?</h3><p>Não. Compartilhe somente o que for confortável e necessário.</p><h3>Posso sair de uma conversa?</h3><p>Sim. Silenciar, bloquear ou denunciar são opções legítimas.</p>']
    return ''.join(out)

data = json.loads(INDEX.read_text())
existing = {x['slug'] for x in data}
for slug, title, excerpt, category, tags, sections in articles:
    if slug in existing: raise SystemExit(f'duplicate slug: {slug}')
    html = render(sections)
    words = len(re.findall(r'\w+', re.sub('<[^>]+>', ' ', html), re.UNICODE))
    if not 800 <= words <= 1500: raise SystemExit(f'bad word count {slug}: {words}')
    entry = {'slug': slug, 'title': title, 'excerpt': excerpt, 'category': category, 'tags': tags, 'body': html, 'content': html, 'author': 'Disque Amizade', 'date': DATE, 'lastModified': DATE, 'readTime': round(words / 155), 'wordCount': words, 'image': '/blog-images/default.png', 'coverImage': '/blog-images/default.png', 'relatedSlugs': []}
    data.append(entry)
    (ROOT / 'public/blog-posts' / f'{slug}.html').write_text(html)
INDEX.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n')
print('added', [(a[0], len(re.findall(r'\w+', re.sub('<[^>]+>', ' ', render(a[5]), flags=re.UNICODE))) ) for a in articles])
